import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"guide/requirements.md","filePath":"guide/requirements.md"}'),i={name:"guide/requirements.md"};function n(s,e,l,d,u,m){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><p>Before installing Weeabooify, make sure your setup meets the following requirements.</p><h2 id="android-version" tabindex="-1">Android Version <a class="header-anchor" href="#android-version" aria-label="Permalink to &quot;Android Version&quot;">​</a></h2><ul><li><strong>Android 12 – 16</strong> (Anti-Entropy variant)</li></ul><div class="warning custom-block"><p class="custom-block-title">Android 15 and below</p><p>If you&#39;re on <strong>Android 15 or below</strong>, use <strong>version 5.6</strong> instead of the latest release.</p></div><h2 id="root-manager" tabindex="-1">Root Manager <a class="header-anchor" href="#root-manager" aria-label="Permalink to &quot;Root Manager&quot;">​</a></h2><p>You need one of the following root solutions:</p><ul><li><a href="https://github.com/topjohnwu/Magisk" target="_blank" rel="noreferrer">Magisk</a></li><li><a href="https://github.com/tiann/KernelSU" target="_blank" rel="noreferrer">KernelSU</a></li><li><a href="https://github.com/SukiSU-Ultra/SukiSU-Ultra" target="_blank" rel="noreferrer">SukiSU</a></li><li><a href="https://github.com/bmax121/APatch" target="_blank" rel="noreferrer">APatch</a></li></ul><h2 id="lsposed-framework" tabindex="-1">LSPosed Framework <a class="header-anchor" href="#lsposed-framework" aria-label="Permalink to &quot;LSPosed Framework&quot;">​</a></h2><ul><li><a href="https://github.com/JingMatrix/LSPosed" target="_blank" rel="noreferrer">LSPosed</a> — optionally paired with <a href="https://github.com/Dr-TSNG/ZygiskNext/releases/latest" target="_blank" rel="noreferrer">ZygiskNext</a> if required by your root setup</li></ul><h2 id="recommended" tabindex="-1">Recommended <a class="header-anchor" href="#recommended" aria-label="Permalink to &quot;Recommended&quot;">​</a></h2><ul><li>A <strong>custom recovery with decryption support</strong> (e.g. OrangeFox, TWRP) is strongly recommended as a fallback in case of bootloop.</li></ul><div class="tip custom-block"><p class="custom-block-title">KernelSU users</p><p>Root access for Weeabooify must be <strong>manually granted</strong> via the KernelSU app.</p></div>',13)])])}const p=r(i,[["render",n]]);export{h as __pageData,p as default};
